/// <summary>
/// Validates the record before it is written to the database.
/// </summary>
/// <remarks>
/// Business rule:
/// When the Agreement Module is Vendor (ModuleInventCustVend::Vend),
/// the METRebateDiscountValue field is mandatory.
/// If it is not provided, the system will throw an error and prevent the save operation.
/// </remarks>
/// <returns>
/// Returns true if validation succeeds; otherwise, false.
/// </returns>
public boolean validateWrite()
{
    boolean ret = next validateWrite();

    // Get the entity data source buffer
    TAMRebateAndDeductionsAgreementHeaderEntity tamRebateAndDeductionsAgreementHeaderEntity = this;

    // Now you can access the actual table fields directly
    ModuleInventCustVend module = tamRebateAndDeductionsAgreementHeaderEntity.AgreementModule;
    METRebateDiscountValue discount = tamRebateAndDeductionsAgreementHeaderEntity.METRebateDiscountValue;

    // Mandatory rule
    if (module == ModuleInventCustVend::Vend
        && !discount)
    {
        error("@MET:RebateDicValueError");
        ret = false;
    }

    return ret;
}
